package com.llmcouncil.mobile

import android.app.*
import android.content.Context
import android.content.Intent
import android.os.IBinder
import androidx.core.app.NotificationCompat
import com.llmcouncil.mobile.data.*
import com.llmcouncil.mobile.domain.AuditStandards
import com.llmcouncil.mobile.domain.RepoAuditEngine
import com.llmcouncil.mobile.model.*
import kotlinx.coroutines.*

class RepoAuditService:Service(){
    companion object{const val ACTION_START="com.llmcouncil.mobile.action.START_REPO_AUDIT";const val ACTION_CANCEL="com.llmcouncil.mobile.action.CANCEL_REPO_AUDIT";const val EXTRA_REPO="repo";const val EXTRA_REF="ref";private const val CHANNEL="repo_audit_runs";private const val NOTIFICATION_ID=4405}
    private val scope=CoroutineScope(SupervisorJob()+Dispatchers.IO);private var active:Job?=null
    override fun onCreate(){super.onCreate();RepoAuditRuntime.initialise(this);createChannel()}
    override fun onStartCommand(intent:Intent?,flags:Int,startId:Int):Int{when(intent?.action){ACTION_CANCEL->{active?.cancel();RepoAuditRuntime.update(this,RepoAuditRuntime.run.value.copy(stage=RepoAuditStage.CANCELLED,finishedAt=System.currentTimeMillis()));stopForeground(STOP_FOREGROUND_REMOVE);stopSelf()};ACTION_START->{val repo=intent.getStringExtra(EXTRA_REPO).orEmpty().trim();val ref=intent.getStringExtra(EXTRA_REF).orEmpty().trim().ifBlank{"main"};if(repo.isNotBlank()&&active?.isActive!=true)startAudit(repo,ref)}};return START_REDELIVER_INTENT}
    private fun startAudit(repoFullName:String,ref:String){startForeground(NOTIFICATION_ID,notification("Loading validated scope…",true));active=scope.launch{val settings=SecureSettings(this@RepoAuditService,auditMode=true);val github=GitHubClient(settings);val engine=RepoAuditEngine(OpenRouterClient(settings),settings,ModelHealthDb(this@RepoAuditService));try{val approved=ScopeManifestStore(this@RepoAuditService).load(ref)?:throw IllegalStateException("Validated scope manifest is missing or failed integrity verification. Re-analyse scope.");if(approved.repoFullName!=repoFullName)throw IllegalStateException("Validated scope belongs to another repository");if(approved.unresolvedFiles>0)throw IllegalStateException("Scope still has ${approved.unresolvedFiles} unresolved files");val checkpoint=RepoAuditRuntime.run.value.takeIf{it.repoFullName==repoFullName&&it.ref==ref&&it.stage!=RepoAuditStage.COMPLETE&&it.scopeManifestHash==approved.manifestHash&&it.auditStandardVersion==AuditStandards.VERSION};var state=RepoAuditRun(repoFullName=repoFullName,ref=ref,scopeManifestHash=approved.manifestHash,auditStandardVersion=AuditStandards.VERSION,stage=RepoAuditStage.SNAPSHOT,startedAt=checkpoint?.startedAt?:System.currentTimeMillis());RepoAuditRuntime.update(this@RepoAuditService,state);val repo=GitHubRepo(repoFullName,ref,false,"","");val snapshot=github.snapshot(repo,ref,approved){current,total,path->notifyProgress("Snapshot $current/$total · ${path.takeLast(38)}",if(total<=0)0 else current*100/total)};val resume=checkpoint?.takeIf{it.commitSha==snapshot.commitSha&&it.scopeManifestHash==approved.manifestHash&&it.auditStandardVersion==AuditStandards.VERSION};state=(resume?:state).copy(repoFullName=repoFullName,ref=ref,commitSha=snapshot.commitSha,scopeManifestHash=approved.manifestHash,auditStandardVersion=AuditStandards.VERSION,stage=RepoAuditStage.INDEPENDENT,requiredFiles=snapshot.requiredFiles.size,excludedFiles=snapshot.excluded.size,excludedManifest=snapshot.excluded,finishedAt=null);RepoAuditRuntime.update(this@RepoAuditService,state);val result=engine.run(snapshot,approved.manifestHash,resume){u->RepoAuditRuntime.update(this@RepoAuditService,u);notifyAudit(u)};RepoAuditRuntime.update(this@RepoAuditService,result);if(result.stage==RepoAuditStage.COMPLETE&&result.finalReport.isNotBlank())RepoAuditHistoryDb(this@RepoAuditService).insertOrReplace(result.repoFullName,result.commitSha,result.scopeManifestHash,result.requiredFiles,result.excludedFiles,result.chairmanModel,result.finalReport,result.startedAt,result.finishedAt?:System.currentTimeMillis());val text=when(result.stage){RepoAuditStage.COMPLETE->"Repository audit finished · tap to view";RepoAuditStage.CANCELLED->"Repository audit cancelled";else->"Repository audit stopped · tap for diagnostics"};manager().notify(NOTIFICATION_ID,notification(text,false,false))}catch(e:CancellationException){RepoAuditRuntime.update(this@RepoAuditService,RepoAuditRuntime.run.value.copy(stage=RepoAuditStage.CANCELLED,finishedAt=System.currentTimeMillis()))}catch(e:Exception){val c=RepoAuditRuntime.run.value;RepoAuditRuntime.update(this@RepoAuditService,c.copy(stage=RepoAuditStage.ERROR,errors=c.errors+("Repository audit" to(e.message?:e.toString())),finishedAt=System.currentTimeMillis()));manager().notify(NOTIFICATION_ID,notification("Repository audit failed · tap for diagnostics",false,false))}finally{stopForeground(STOP_FOREGROUND_DETACH);stopSelf()}}}
    private fun notifyAudit(run:RepoAuditRun){val text=when(run.stage){RepoAuditStage.SNAPSHOT->"Building repository snapshot";RepoAuditStage.INDEPENDENT->{val done=run.modelAudits.count{it.complete};val p=run.modelAudits.lastOrNull();val pct=p?.let{if(it.requiredCount==0)0 else it.coveredCount*100/it.requiredCount}?:0;"Evidence audits · $done complete · validated $pct%"};RepoAuditStage.PEER_REVIEW->"Anonymous peer review";RepoAuditStage.VERIFY->"Adversarial verification";RepoAuditStage.CHAIRMAN->"Final synthesis";RepoAuditStage.COMPLETE->"Repository audit finished";RepoAuditStage.ERROR->"Repository audit stopped";RepoAuditStage.CANCELLED->"Repository audit cancelled";else->"Repository audit running"};manager().notify(NOTIFICATION_ID,notification(text,run.stage !in listOf(RepoAuditStage.COMPLETE,RepoAuditStage.ERROR,RepoAuditStage.CANCELLED)))}
    private fun notifyProgress(text:String,pct:Int){manager().notify(NOTIFICATION_ID,notification(text,false,true,pct))}
    private fun manager()=getSystemService(Context.NOTIFICATION_SERVICE)as NotificationManager
    private fun notification(text:String,indeterminate:Boolean,ongoing:Boolean=true,progress:Int?=null):Notification{val pending=PendingIntent.getActivity(this,4405,Intent(this,RepoAuditActivity::class.java),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);val cancel=PendingIntent.getService(this,4406,Intent(this,RepoAuditService::class.java).apply{action=ACTION_CANCEL},PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);val b=NotificationCompat.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.stat_notify_sync).setContentTitle("OmniCouncil · Repository Audit").setContentText(text).setContentIntent(pending).setOnlyAlertOnce(true).setOngoing(ongoing).setPriority(NotificationCompat.PRIORITY_LOW);if(ongoing)b.addAction(android.R.drawable.ic_menu_close_clear_cancel,"Cancel",cancel);when{progress!=null->b.setProgress(100,progress.coerceIn(0,100),false);indeterminate->b.setProgress(0,0,true);else->b.setProgress(0,0,false)};return b.build()}
    private fun createChannel(){manager().createNotificationChannel(NotificationChannel(CHANNEL,"Repository audits",NotificationManager.IMPORTANCE_LOW).apply{description="Progress and completion for OmniCouncil repository audits"})}
    override fun onDestroy(){super.onDestroy();if(active?.isCompleted==true)scope.cancel()};override fun onBind(intent:Intent?):IBinder?=null
}
